#pragma once

// The unified route encoder on the microcontroller: the same network as
// include/continuous/unified_encoder.hpp (obstacle and body token MLPs, two
// self-attention layers over the joint set, head on [anchor obstacle token,
// mean obstacle token, mean body token, 8-number query]), distilled to a
// narrow width, with int8 weights and one float scale per output row
// (unified_weights.hpp, generated by benchmarks/learning/unified_study.py).
// Drone tokens in the start-goal path frame as in engine/oneshot_policy.hpp
// (UnifiedPolicy). Fixed-size float code, no heap. Scores only order route
// cuts; acceptance is the checker.

#include <tinysdp_ct_embedded/unified_weights.hpp>

#include <cmath>
#include <cstdint>
#include <limits>

namespace tinysdp_ct_embedded {

namespace unified_detail {
template<int Rows, int Cols>
inline void linear_q8(const std::int8_t (&q)[Rows * Cols], const float (&scale)[Rows], const float (&b)[Rows],
                      const float* x, float* y, bool relu) {
    for (int r = 0; r < Rows; ++r) {
        const std::int8_t* row = q + r * Cols;
        float acc = 0;
        for (int c = 0; c < Cols; ++c) acc += float(row[c]) * x[c];
        const float v = b[r] + scale[r] * acc;
        y[r] = relu && v < 0.f ? 0.f : v;
    }
}
}  // namespace unified_detail

template<int MaxN>
class UnifiedEncoder {
public:
    static constexpr int W = unified_weights::kWidth, H = unified_weights::kHeads, Dh = W / H, kBody = 3, kHidden = unified_weights::kHidden;
    static constexpr int kTokens = MaxN + kBody;

    template<class Sphere>
    void encode(const float* start, const float* goal, const Sphere* spheres, int n) {
        namespace w = unified_weights;
        using unified_detail::linear_q8;
        n_ = n < MaxN ? n : MaxN;
        float fwd[3], dist2 = 0;
        for (int c = 0; c < 3; ++c) { fwd[c] = goal[c] - start[c]; dist2 += fwd[c] * fwd[c]; mid_[c] = 0.5f * (start[c] + goal[c]); }
        length_ = std::fmax(1e-9f, 0.5f * std::sqrt(dist2));
        for (float& v : fwd) v /= 2 * length_;
        for (int c = 0; c < 3; ++c) f_[c] = fwd[c];
        frame();
        float clearance[MaxN];
        for (int k = 0; k < n_; ++k) {
            float best = std::numeric_limits<float>::infinity(), when = 0;
            for (int i = 0; i <= 200; ++i) {
                float d2 = 0;
                for (int c = 0; c < 3; ++c) {
                    const float q = start[c] + (i / 200.f) * (goal[c] - start[c]) - float(spheres[k].center[c]);
                    d2 += q * q;
                }
                const float d = std::sqrt(d2) - float(spheres[k].radius);
                if (d < best) { best = d; when = i / 200.f; }
            }
            clearance[k] = best;
            float rel[3], token[8], hidden[W];
            for (int c = 0; c < 3; ++c) rel[c] = float(spheres[k].center[c]) - mid_[c];
            token[0] = dot(rel, f_) / length_; token[1] = dot(rel, e1_) / length_; token[2] = dot(rel, e2_) / length_;
            token[3] = float(spheres[k].radius) / length_; token[4] = best / length_; token[5] = when;
            token[6] = 1.f / 8; token[7] = n / 12.f;
            linear_q8<W, 8>(w::obs_0_weight_q, w::obs_0_weight_s, w::obs_0_bias, token, hidden, true);
            linear_q8<W, W>(w::obs_2_weight_q, w::obs_2_weight_s, w::obs_2_bias, hidden, h_[k], false);
        }
        for (int k = 0; k < n_; ++k) {  // clearance rank (stable)
            int r = 0;
            for (int j = 0; j < n_; ++j) if (clearance[j] < clearance[k] || (clearance[j] == clearance[k] && j < k)) ++r;
            rank_[k] = r;
        }
        for (int b = 0; b < kBody; ++b) {
            const float t = 0.25f * (b + 1);
            const float token[6] = {2 * t - 1, 0, 0, 0, 1.f / 8, t};
            float hidden[W];
            linear_q8<W, 6>(w::arm_0_weight_q, w::arm_0_weight_s, w::arm_0_bias, token, hidden, true);
            linear_q8<W, W>(w::arm_2_weight_q, w::arm_2_weight_s, w::arm_2_bias, hidden, h_[n_ + b], false);
        }
        attention<0>();
        attention<1>();
        for (int c = 0; c < W; ++c) {
            float so = 0, sb = 0;
            for (int k = 0; k < n_; ++k) so += h_[k][c];
            for (int b = 0; b < kBody; ++b) sb += h_[n_ + b][c];
            pooled_obs_[c] = n_ ? so / n_ : 0.f;
            pooled_body_[c] = sb / kBody;
        }
    }

    // Score of a cut on obstacle `o` in direction index `dir` (of `directions`
    // transverse directions; u is its unit vector) at straight-path time tau.
    float score(int o, const float* u, int dir, int directions, float tau) const {
        namespace w = unified_weights;
        using unified_detail::linear_q8;
        float x[3 * W + 8], a[kHidden], b[kHidden], y[2];
        for (int c = 0; c < W; ++c) { x[c] = h_[o][c]; x[W + c] = pooled_obs_[c]; x[2 * W + c] = pooled_body_[c]; }
        const float angle = 2 * 3.14159265358979323846f * dir / directions;
        float* q = x + 3 * W;
        q[0] = dot(u, f_); q[1] = dot(u, e1_); q[2] = dot(u, e2_); q[3] = std::cos(angle); q[4] = std::sin(angle);
        q[5] = tau; q[6] = 1.f / 8; q[7] = std::fmin(1.f, rank_[o] / 4.f);
        linear_q8<kHidden, 3 * W + 8>(w::head_0_weight_q, w::head_0_weight_s, w::head_0_bias, x, a, true);
        linear_q8<kHidden, kHidden>(w::head_2_weight_q, w::head_2_weight_s, w::head_2_bias, a, b, true);
        linear_q8<2, kHidden>(w::head_4_weight_q, w::head_4_weight_s, w::head_4_bias, b, y, false);
        const float logit = y[0];
        const float lp = logit >= 0.f ? -std::log1p(std::exp(-logit)) : logit - std::log1p(std::exp(logit));
        return lp - y[1];
    }

private:
    static float dot(const float* a, const float* b) { return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]; }
    void frame() {
        float ref[3] = {0, 0, 1};
        if (std::fabs(f_[2]) >= 0.9f) { ref[1] = 1; ref[2] = 0; }
        e1_[0] = f_[1] * ref[2] - f_[2] * ref[1]; e1_[1] = f_[2] * ref[0] - f_[0] * ref[2]; e1_[2] = f_[0] * ref[1] - f_[1] * ref[0];
        const float n1 = std::sqrt(dot(e1_, e1_));
        for (float& v : e1_) v /= n1;
        e2_[0] = f_[1] * e1_[2] - f_[2] * e1_[1]; e2_[1] = f_[2] * e1_[0] - f_[0] * e1_[2]; e2_[2] = f_[0] * e1_[1] - f_[1] * e1_[0];
        const float n2 = std::sqrt(dot(e2_, e2_));
        for (float& v : e2_) v /= n2;
    }
    // h = LayerNorm(h + OutProj(MHA(h))) over the n_ + kBody tokens, one head at a time.
    template<int L>
    void attention() {
        namespace w = unified_weights;
        using unified_detail::linear_q8;
        const int n = n_ + kBody;
        const std::int8_t* in_q = L == 0 ? w::blocks_0_in_proj_weight_q : w::blocks_1_in_proj_weight_q;
        const float* in_s = L == 0 ? w::blocks_0_in_proj_weight_s : w::blocks_1_in_proj_weight_s;
        const float* in_b = L == 0 ? w::blocks_0_in_proj_bias : w::blocks_1_in_proj_bias;
        const auto project = [&](int row, const float* x) {
            const std::int8_t* q = in_q + row * W;
            float acc = 0;
            for (int c = 0; c < W; ++c) acc += float(q[c]) * x[c];
            return in_b[row] + in_s[row] * acc;
        };
        const float inv_sqrt = 1.f / std::sqrt(float(Dh));
        for (int head = 0; head < H; ++head) {
            for (int k = 0; k < n; ++k)
                for (int d = 0; d < Dh; ++d) { k_[k][d] = project(W + head * Dh + d, h_[k]); v_[k][d] = project(2 * W + head * Dh + d, h_[k]); }
            for (int r = 0; r < n; ++r) {
                float q[Dh], p[kTokens], top = -std::numeric_limits<float>::infinity(), sum = 0;
                for (int d = 0; d < Dh; ++d) q[d] = project(head * Dh + d, h_[r]);
                for (int k = 0; k < n; ++k) {
                    float s = 0;
                    for (int d = 0; d < Dh; ++d) s += q[d] * k_[k][d];
                    p[k] = s * inv_sqrt;
                    if (p[k] > top) top = p[k];
                }
                for (int k = 0; k < n; ++k) { p[k] = std::exp(p[k] - top); sum += p[k]; }
                for (int d = 0; d < Dh; ++d) {
                    float acc = 0;
                    for (int k = 0; k < n; ++k) acc += p[k] * v_[k][d];
                    attended_[r][head * Dh + d] = acc / sum;
                }
            }
        }
        for (int r = 0; r < n; ++r) {
            float y[W];
            if (L == 0) linear_q8<W, W>(w::blocks_0_out_proj_weight_q, w::blocks_0_out_proj_weight_s, w::blocks_0_out_proj_bias, attended_[r], y, false);
            else linear_q8<W, W>(w::blocks_1_out_proj_weight_q, w::blocks_1_out_proj_weight_s, w::blocks_1_out_proj_bias, attended_[r], y, false);
            float mean = 0, var = 0;
            for (int c = 0; c < W; ++c) { y[c] += h_[r][c]; mean += y[c]; }
            mean /= W;
            for (int c = 0; c < W; ++c) var += (y[c] - mean) * (y[c] - mean);
            const float inv = 1.f / std::sqrt(var / W + 1e-5f);
            const float* g = L == 0 ? w::norms_0_weight : w::norms_1_weight;
            const float* b = L == 0 ? w::norms_0_bias : w::norms_1_bias;
            for (int c = 0; c < W; ++c) h_[r][c] = (y[c] - mean) * inv * g[c] + b[c];
        }
    }

    float h_[kTokens][W] = {}, attended_[kTokens][W] = {}, k_[kTokens][Dh] = {}, v_[kTokens][Dh] = {};
    float pooled_obs_[W] = {}, pooled_body_[W] = {}, f_[3] = {}, e1_[3] = {}, e2_[3] = {}, mid_[3] = {}, length_ = 1;
    int rank_[MaxN] = {};
    int n_ = 0;
};

}  // namespace tinysdp_ct_embedded
